<script setup lang="ts">
import { nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue"; import * as echarts from "echarts"; import { api, money, today } from "../api";
const accounts=ref<any[]>([]), plans=ref<any[]>([]), selectedAccount=ref<number>(), selectedPlan=ref<number>(), series=ref<any[]>([]), message=ref(""), error=ref(""); const chartEl=ref<HTMLElement>(); let chart:echarts.ECharts|undefined;
async function load(){try{[accounts.value,plans.value]=await Promise.all([api<any[]>("/simulations/accounts"),api<any[]>("/plans")]);selectedAccount.value ??=accounts.value[0]?.id;selectedPlan.value ??=plans.value[0]?.id;await loadSeries();}catch(e:any){error.value=e.message;}} async function loadSeries(){if(!selectedAccount.value)return;try{series.value=await api<any[]>(`/simulations/${selectedAccount.value}/series`);await nextTick();render();}catch(e:any){if(e.status!==400)error.value=e.message;series.value=[];}} function render(){if(!chartEl.value)return;chart?.dispose();chart=echarts.init(chartEl.value);chart.setOption({grid:{left:56,right:20,top:24,bottom:34},tooltip:{trigger:"axis"},xAxis:{type:"category",data:series.value.map(x=>x.date),axisLine:{lineStyle:{color:"#586661"}},axisLabel:{color:"#9ca8a3"}},yAxis:{scale:true,splitLine:{lineStyle:{color:"#2a3634"}},axisLabel:{color:"#9ca8a3"}},series:[{type:"line",name:"总资产",data:series.value.map(x=>x.total_assets),smooth:true,symbol:"none",lineStyle:{color:"#d6ff4e",width:2},areaStyle:{color:"rgba(214,255,78,.08)"}},{type:"line",name:"投入",data:series.value.map(x=>x.external_cash_flow),symbol:"none",lineStyle:{color:"#7dc9ff"}}]});}
async function run(){if(!selectedAccount.value||!selectedPlan.value)return;try{const r=await api<any>("/simulations/run-weekly",{method:"POST",body:JSON.stringify({account_id:selectedAccount.value,plan_id:selectedPlan.value,week_date:today()})});message.value=r.idempotent?"本周已执行过此计划，未重复记账。":"本周模拟交易已写入 SQLite。";await load();}catch(e:any){error.value=e.message;}} async function recalc(){if(!selectedAccount.value)return;try{await api(`/simulations/${selectedAccount.value}/recalculate`,{method:"POST"});message.value="账户已按冻结交易记录重新计算。";await load();}catch(e:any){error.value=e.message;}}
onMounted(()=>{load();window.addEventListener("resize",render);});onBeforeUnmount(()=>{chart?.dispose();window.removeEventListener("resize",render);});watch(selectedAccount,loadSeries);
</script>
<template><section class="panel"><div class="panel-head"><div><h2>每周定投模拟</h2><p class="muted">按本地行情、计划、费用和手数规则执行；从不连接券商或发送订单。</p></div><div class="toolbar"><select class="select" v-model="selectedAccount"><option v-for="account in accounts" :value="account.id">{{account.name}}</option></select><select class="select" v-model="selectedPlan"><option v-for="plan in plans" :value="plan.id">{{plan.name}}</option></select><button class="button" @click="run">运行本周模拟</button></div></div><div v-if="message" class="status">{{message}}</div><div v-if="error" class="status error">{{error}}</div><div ref="chartEl" class="chart"></div><div class="split"><span class="muted">收益序列来自模拟账户每日快照。</span><button class="button ghost" @click="recalc">从账本重新计算</button></div></section><section class="section-gap grid cols-3"><article v-for="account in accounts" class="panel metric"><label>{{account.name}}</label><strong>{{money(Number(account.cash_balance)+Number(account.portfolio_value))}}</strong><span class="muted">现金 {{money(account.cash_balance)}} · 市值 {{money(account.portfolio_value)}}</span></article></section></template>
